// ─── SPARKLINE GENERATOR ──────────────────────────────
function generateSparkline(trend, width=90, height=32) {
  const pts = 7;
  const seeds = {
    up:   [0.3,0.35,0.4,0.45,0.55,0.7,0.85],
    down: [0.75,0.70,0.65,0.55,0.45,0.35,0.25],
    flat: [0.5,0.51,0.49,0.50,0.52,0.49,0.50],
    mixed:[0.4,0.6,0.35,0.65,0.4,0.55,0.48],
  };
  const base = seeds[trend] || seeds.up;
  const noise = base.map(v => Math.min(0.95, Math.max(0.05, v + (Math.random()-0.5)*0.08)));
  const xs = noise.map((_, i) => (i / (pts-1)) * width);
  const ys = noise.map(v => height - v * height);
  const color = trend === 'down' ? '#ea3943' : trend === 'flat' ? '#808a9d' : '#16c784';
  const fillColor = trend === 'down' ? 'rgba(234,57,67,0.08)' : trend === 'flat' ? 'rgba(128,138,157,0.06)' : 'rgba(22,199,132,0.08)';
  const pathD = xs.map((x,i) => `${i===0?'M':'L'}${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ');
  const fillD = `${pathD} L${width},${height} L0,${height} Z`;
  return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><path d="${fillD}" fill="${fillColor}" stroke="none"/><path d="${pathD}" stroke="${color}" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

function formatPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toFixed(4).replace(/\.?0+$/,'').padEnd(p < 10 ? 5 : 4, '');
  if (p >= 0.0001) return '$' + p.toFixed(6);
  return '$' + p.toFixed(8);
}

function pctClass(v) {
  return v > 0 ? 'pct-up' : v < 0 ? 'pct-down' : 'pct-neutral';
}

function pctStr(v) {
  const sign = v > 0 ? '+' : '';
  return `${sign}${v.toFixed(2)}%`;
}

// ─── RENDER TABLE ─────────────────────────────────────
let currentCat = 'top';
let currentNet = 'all';
let currentPage = 1;
const ROWS_PER_PAGE = 100;

function getCoinColor(index) { return coinColors[index % coinColors.length]; }

function filterCoins() {
  let coins = [...coinData];
  if (currentCat === 'trending') {
    coins = coins.sort((a,b) => Math.abs(b.h24) - Math.abs(a.h24));
  } else if (currentCat === 'watchlist') {
    coins = coins.filter(c => ['BTC','ETH','SOL','BNB','XRP'].includes(c.ticker));
  } else if (currentCat === 'prediction') {
    coins = coins.filter(c => c.rank <= 20);
  } else if (currentCat === 'visited') {
    coins = coins.sort(() => Math.random() - 0.5).slice(0, 30);
  } else if (currentCat === 'new') {
    coins = coins.filter(c => c.rank > 80);
  }
  if (currentNet === 'solana') {
    coins = coins.filter(c => ['SOL','BONK','WIF','POPCAT','JUP','ORCA','RAY','MYRO','JTO','PYTH','W'].includes(c.ticker));
  } else if (currentNet === 'ethereum') {
    coins = coins.filter(c => ['ETH','USDT','USDC','UNI','LINK','AAVE','MKR','COMP','YFI','LDO','SNX','CRV','BAL','RPL'].includes(c.ticker));
  } else if (currentNet === 'bsc') {
    coins = coins.filter(c => ['BNB','CAKE'].includes(c.ticker));
  } else if (currentNet === 'base') {
    coins = coins.filter(c => ['ETH','OP','ARB'].includes(c.ticker));
  }
  return coins;
}

function renderTable() {
  const coins = filterCoins();
  const tbody = document.getElementById('cryptoTableBody');
  if (coins.length === 0) {
    tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:40px;color:var(--gray);">No cryptocurrencies match the selected filters.</td></tr>`;
    return;
  }
  tbody.innerHTML = coins.map((c, i) => {
    const color = getCoinColor(c.rank - 1);
    const abbr = c.ticker.substring(0, 2);
    return `
    <tr>
      <td class="td-center">
        <span class="star-btn" onclick="toggleStar(this)">☆</span>
        <div class="rank-num">${c.rank}</div>
      </td>
      <td class="td-left">
        <div class="coin-cell">
          <div class="coin-icon" style="background:${color}">${abbr}</div>
          <div>
            <div class="coin-name">${c.name}</div>
            <div class="coin-ticker">${c.ticker}</div>
          </div>
        </div>
      </td>
      <td><span class="price-cell">${formatPrice(c.price)}</span></td>
      <td class="col-1h"><span class="pct-cell ${pctClass(c.h1)}">${pctStr(c.h1)}</span></td>
      <td class="col-24h"><span class="pct-cell ${pctClass(c.h24)}">${pctStr(c.h24)}</span></td>
      <td class="col-7d"><span class="pct-cell ${pctClass(c.d7)}">${pctStr(c.d7)}</span></td>
      <td class="col-mcap"><span class="mcap-cell">${c.mcap}</span></td>
      <td class="col-vol"><span class="mcap-cell">${c.vol}</span></td>
      <td class="col-supply"><span class="supply-cell">${c.supply}</span></td>
      <td class="td-center col-spark sparkline-cell">${generateSparkline(c.trend)}</td>
    </tr>`;
  }).join('');

  // Update page info
  document.getElementById('pageInfo').textContent = `Showing 1–${coins.length} of 8,364 assets`;
}

// ─── PAGINATION ───────────────────────────────────────
function renderPagination() {
  const nums = document.getElementById('pageNums');
  const pages = [1,2,3,4];
  nums.innerHTML = `
    <button class="page-arrow" onclick="changePage(${currentPage-1})">‹</button>
    ${pages.map(p => `<button class="page-num ${p===currentPage?'active':''}" onclick="changePage(${p})">${p}</button>`).join('')}
    <span class="page-num ellipsis">…</span>
    <button class="page-num" onclick="changePage(84)">84</button>
    <button class="page-arrow" onclick="changePage(${currentPage+1})">›</button>
  `;
}

function changePage(p) {
  if (p < 1 || p > 84) return;
  currentPage = p;
  renderPagination();
  window.scrollTo({top: 0, behavior: 'smooth'});
}

// ─── TAB INTERACTIONS ─────────────────────────────────
document.getElementById('categoryTabs').addEventListener('click', e => {
  const btn = e.target.closest('[data-cat]');
  if (!btn) return;
  document.querySelectorAll('[data-cat]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  currentCat = btn.dataset.cat;
  renderTable();
});

document.getElementById('networkTabs').addEventListener('click', e => {
  const btn = e.target.closest('[data-net]');
  if (!btn) return;
  document.querySelectorAll('[data-net]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  currentNet = btn.dataset.net;
  renderTable();
});

// ─── COLUMNS TOGGLE ───────────────────────────────────
const columns = [
  {key:'col-1h', label:'1h %', checked:true},
  {key:'col-24h', label:'24h %', checked:true},
  {key:'col-7d', label:'7d %', checked:true},
  {key:'col-mcap', label:'Market Cap', checked:true},
  {key:'col-vol', label:'Volume (24h)', checked:true},
  {key:'col-supply', label:'Circulating Supply', checked:true},
  {key:'col-spark', label:'Last 7 Days', checked:true},
];

function renderColToggles() {
  const list = document.getElementById('colToggleList');
  list.innerHTML = columns.map(c => `
    <label class="col-toggle" onclick="toggleCol('${c.key}', this)">
      <span class="toggle-check ${c.checked?'checked'}">✓</span>
      <span>${c.label}</span>
    </label>
  `).join('');
}

function toggleCol(key, el) {
  const col = columns.find(c => c.key === key);
  if (!col) return;
  col.checked = !col.checked;
  const check = el.querySelector('.toggle-check');
  check.classList.toggle('checked', col.checked);
  check.textContent = col.checked ? '✓' : '';
  document.querySelectorAll(`.${key}`).forEach(td => {
    td.classList.toggle('hidden', !col.checked);
  });
}

function togglePanel(panelId, btnId) {
  const panel = document.getElementById(panelId);
  const btn = document.getElementById(btnId);
  const isOpen = panel.classList.contains('show');
  // Close all panels first
  document.querySelectorAll('.dropdown-panel').forEach(p => p.classList.remove('show'));
  document.querySelectorAll('.control-btn').forEach(b => b.classList.remove('active'));
  if (!isOpen) {
    panel.classList.add('show');
    btn.classList.add('active');
  }
}

// Close panels on outside click
document.addEventListener('click', e => {
  if (!e.target.closest('.control-btn') && !e.target.closest('.dropdown-panel')) {
    document.querySelectorAll('.dropdown-panel').forEach(p => p.classList.remove('show'));
    document.querySelectorAll('.control-btn').forEach(b => b.classList.remove('active'));
  }
});

// ─── MARKET SUMMARY EXPAND ────────────────────────────
function toggleSummary(btn) {
  const extra = document.getElementById('summaryExtra');
  const isOpen = extra.classList.contains('show');
  extra.classList.toggle('show', !isOpen);
  btn.textContent = isOpen ? 'Read More ▾' : 'Show Less ▴';
}

// ─── STAR BUTTON ─────────────────────────────────────
function toggleStar(el) {
  const isStarred = el.classList.contains('starred');
  el.classList.toggle('starred', !isStarred);
  el.textContent = isStarred ? '☆' : '★';
}

// ─── PROMO BANNER CAROUSEL ───────────────────────────
let promoIndex = 0;
const promoSlides = document.querySelectorAll('.promo-slide');
const promoDots = document.getElementById('promoDots');

function initPromo() {
  promoSlides.forEach((_, i) => {
    const dot = document.createElement('button');
    dot.className = 'promo-dot' + (i===0?' active':'');
    dot.onclick = () => goPromo(i);
    promoDots.appendChild(dot);
  });
}

function goPromo(idx) {
  promoIndex = idx;
  document.getElementById('promoSlides').style.transform = `translateY(-${idx * 36}px)`;
  document.querySelectorAll('.promo-dot').forEach((d,i) => d.classList.toggle('active', i===idx));
}

function closeBanner() {
  document.getElementById('promoBanner').style.display = 'none';
}

let promoTimer = setInterval(() => {
  goPromo((promoIndex + 1) % promoSlides.length);
}, 4000);

// ─── INIT ─────────────────────────────────────────────
initPromo();
renderColToggles();
renderTable();
renderPagination();
</script>
</body>
</html>
